@@ -120,6 +120,14 @@
+// light-weight ring-buffer write (single writer)
+static inline void ring_write_event(uint32_t tag, uint64_t ts) {
+  uint64_t idx = ring_head.fetch_add(1, std::memory_order_relaxed) & RING_MASK;
+  entries[idx].ts = ts; entries[idx].tag = tag;
+}
